// ---------- display ----------
let VW = 320, VH = 180;
const disp = document.getElementById('c');
const dg = disp.getContext('2d');
const [buf, g] = canvas(VW, VH);
// The view is 320x180, or a zoomed-out size picked from the display so the pixel scale stays an integer and the game never shrinks on screen:
// the zoom drops the scale by a third and fills the display with it, capped at 640x360 (twice the world).
let viewMode = 'normal';
function viewFor(mode) {
  if (mode !== 'zoom') return [320, 180];
  const dw = innerWidth || 1280, dh = innerHeight || 720;
  const S0 = Math.max(1, Math.floor(Math.min(dw / 320, dh / 180))), S1 = Math.max(1, Math.floor(S0 / 1.5));
  return [Math.max(320, Math.min(640, Math.floor(dw / S1))), Math.max(180, Math.min(360, Math.floor(dh / S1)))];
}
function setView(mode) {
  viewMode = mode; const [w, h] = viewFor(mode); if (VW === w && VH === h) return;
  VW = w; VH = h; buf.width = w; buf.height = h; g.imageSmoothingEnabled = false; resize(); if (L) bakeAll(L.palette || {});
}
let S = 3, offX = 0, offY = 0, scanPat = null, DPR = 1;
function resize() {
  DPR = Math.max(1, Math.min(3, (typeof devicePixelRatio === 'number' && devicePixelRatio) || 1));
  const cw = innerWidth || 1280, ch = innerHeight || 720;
  disp.width = Math.round(cw * DPR); disp.height = Math.round(ch * DPR);
  disp.style.width = cw + 'px'; disp.style.height = ch + 'px';
  S = Math.max(1, Math.floor(Math.min(disp.width / VW, disp.height / VH)));
  let cap = 'auto'; try { cap = SET.scale; } catch {} // SET is declared below; the first resize runs before it exists
  if (cap !== 'auto') S = Math.min(S, cap);
  scanPat = null;
  offX = Math.floor((disp.width - VW * S) / 2); offY = Math.floor((disp.height - VH * S) / 2);
  dg.imageSmoothingEnabled = false;
}
addEventListener('resize', () => { if (viewMode === 'zoom') setView('zoom'); resize(); }); resize();
const q = new URLSearchParams(location.search);

// ---------- settings + progress ----------
const SET = { font: 'press', ink: 'parchment', uiTheme: 'oak', music: true, sfx: 0.5, musicVol: 0.8, shake: true, sfxFiles: true, voices: true, hitstop: true, numbers: true, timer: true, ambient: true, difficulty: 'normal', iron: false, zoom: 'close', hud: 'full', filter: 'none', foeBars: true, lookDown: true, bossIntro: true, rumble: true, tenths: true, flashes: true, vignette: true, weather: true, impact: true, tips: true, blockToggle: false, textFast: false, reduceMotion: false, swapZX: false, scanlines: false, scale: 'auto', speed: 0.6, assist: false, ambVol: 1, uiVol: 0.8, bigText: false, colorSafe: false, fps: false, bright: 1, shakeAmt: 1, parallax: 'full', tint: 'full', parts: 'normal', rim: false, grain: false, boxes: 'off' };
const TIER = { causeway: 2.25, frost: 2.2, hunt: 2.0, quarry: 2.1, skyship: 2.3, waymeet: 1.9, deep: 2.2, undercrown: 1.5, underleaf: 0.7, lamplit: 2.05, hurricane: 1.9, wood: 0, marsh: 0.15, stockade: 0.3, spore: 0.45, kings: 0.6, scree: 0.75, hanging: 0.9, spire: 1, moor: 1.1, storm: 1.2, crown: 1.3, longwater: 1.45, reef: 1.6, flotilla: 1.75 }; // how far up the slope a level sits
const tierOf = id => TIER[id] || 0; const curId = () => (LEVELS[levelIndex] || {}).id;
// DIFFICULTY is chosen per wood, on the map (up and down on a level's card): how much everything hurts you,
// how much it takes to put a foe down, and a boss on its own dial. The Settings value is the default for a wood
// you have not set; from the pause menu it sets the wood you are in.
const DIFF = { easy: { take: 0.6, ehp: 0.75, bhp: 0.7, label: 'EASY', col: '#8fd160' }, normal: { take: 0.8, ehp: 0.9, bhp: 0.9, label: 'NORMAL', col: '#ffd36b' }, hard: { take: 1.4, ehp: 1.45, bhp: 1.5, label: 'HARD', col: '#ff6b6b' }, expert: { take: 1.8, ehp: 1.85, bhp: 2.1, label: 'EXPERT', col: '#c9a0ff' } };   /* EXPERT: they hit nearly twice as hard and take twice the killing */
const diffOf = id => (PROG.diff && DIFF[PROG.diff[id]] ? PROG.diff[id] : DIFF[SET.difficulty] ? SET.difficulty : 'normal');
const diffNow = () => DIFF[diffOf(curId())];
const DIFFS = ['easy', 'normal', 'hard', 'expert'], SCALES = ['auto', 2, 3, 4];
try { Object.assign(SET, JSON.parse(localStorage.getItem('bracken.settings') || '{}')); } catch {}
// THE WORLD SLOWED DOWN, AND AN OLD SETTINGS FILE MUST NOT HOLD IT BACK. Anyone who has played before has a
// saved `speed: 1` in their settings, which would silently keep them at the old pace. Take the new default
// once, and never touch it again - if they turn it back up, that is their choice and it sticks.
if (!SET.speedV2) { SET.speed = 0.6; SET.speedV2 = 1; try { localStorage.setItem('bracken.settings', JSON.stringify(SET)); } catch {} }
function saveSettings() { try { localStorage.setItem('bracken.settings', JSON.stringify(SET)); } catch {} }
function applySettings() { setVolume(SET.sfx); setMusicVolume(SET.musicVol); music.set(SET.music); setSfxFiles(SET.sfxFiles); setVoices(SET.voices !== false); setUiVolume(SET.uiVol); setAmbientVolume(SET.ambVol); resize(); }
applySettings();
// Progress lives in one of three save slots. The old single save becomes slot 1 the first time it is read.
const PROG = {}; const SLOTS = 3; let slot = 0, slotI = 0, slotMsg = '', slotMsgT = 0;
try { slot = Math.max(0, Math.min(SLOTS - 1, +(localStorage.getItem('bracken.slot') || 0))); } catch {}
const slotKey = i => 'bracken.progress.' + i;
function readSlot(i) { try { const raw = localStorage.getItem(slotKey(i)) || (i === 0 ? localStorage.getItem('bracken.progress') : null); return raw ? JSON.parse(raw) : null; } catch { return null; } }
function progDefaults() { if (!PROG.heroes) PROG.heroes = { knight: true }; if (!PROG.hero) PROG.hero = 'knight'; if (!PROG.music) PROG.music = { select: true }; if (!PROG.music.select) PROG.music.select = true; PROG.coins = PROG.coins || 0; PROG.skins = PROG.skins || { bracken: true }; PROG.skin = PROG.skin || 'bracken'; PROG.swords = PROG.swords || { steel: true }; PROG.sword = PROG.sword || 'steel'; PROG.items = PROG.items || {}; PROG.charms = PROG.charms || {}; PROG.done = PROG.done || {}; PROG.charmOf = PROG.charmOf || {};
  if (!PROG.perHero) { PROG.perHero = 1;                     /* the save's progress belongs to whoever was carrying it */
    const h = PROG.hero || 'knight', d = PROG.done[h] = PROG.done[h] || {};
    for (const lv of LEVELS) if (!lv.hidden && PROG[lv.id] && PROG[lv.id].cleared) d[lv.id] = 1;
    if (PROG.charm) PROG.charmOf[h] = PROG.charm; }
  /* a secret wood cleared before secret woods counted: credit it to the hero carrying the save, once */
  for (const lv of LEVELS) if (lv.secret && PROG[lv.id] && PROG[lv.id].cleared && !Object.values(PROG.done || {}).some(dd => dd && dd[lv.id])) { const hh = PROG.hero || 'knight'; PROG.done[hh] = PROG.done[hh] || {}; PROG.done[hh][lv.id] = 1; }
  PROG.ranks = PROG.ranks || {}; if (!PROG.skill && PROG.items.shieldThrow) PROG.skill = 'shieldThrow';
  { const OLD = { vigour: [40, 60, 90, 130, 180], breath: [40, 60, 90, 130, 180], recovery: [60, 100, 160], temper: [50, 80, 120, 170, 230], footing: [60, 100, 160] }; let back = 0; for (const id in OLD) for (let r = 0; r < (PROG.ranks[id] || 0); r++) back += OLD[id][r] || 0; if (back) { PROG.coins += back; PROG.ranks = {}; PROG.refundNote = back; } } // the training went: its gold comes back
  /* THE MEDAL PURSE, PAID BACK: medals won before medals paid gold are paid once, in full, when the save is next opened */
  if (!PROG.medalPurseGranted) { const PURSE = [0, 20, 45, 90]; let back = 0; for (const lv of LEVELS) { const m = PROG[lv.id] && PROG[lv.id].medal; if (m) back += PURSE[m] || 0; }
    PROG.medalPurseGranted = true; if (back) { PROG.coins = (PROG.coins || 0) + back; PROG.medalPurseBack = back; } }
  if (!PROG.skillRefund) { const OLD = { shieldThrow: 80, groundSlam: 90, fireWall: 80, cinderStep: 90, risingCut: 100, vent: 100, kindle: 90, wisp: 120 }; let back = 0; for (const id in OLD) if (PROG.items[id]) { back += OLD[id]; delete PROG.items[id]; } PROG.skillRefund = true; if (back) { PROG.coins += back; PROG.refundNote = (PROG.refundNote || 0) + back; } } // the skills left the store for the trees: their gold comes back
  PROG.talents = PROG.talents || {}; PROG.tonics = PROG.tonics || 0;
  /* THE TREES CHANGED (a tree's worth of points, capstones, no stat nodes): a save bought in the old trees gets every point back, once, and is told so.
     (TREE is not built yet the first time a slot loads, so this cannot ask it anything: nothing was bought in the new trees, so no skill is still owned.) */
  if ((PROG.talentVersion || 1) < 2) { const had = Object.values(PROG.talents).some(mm => mm && Object.values(mm).some(v => v)); PROG.talents = {}; PROG.skill = 'none'; PROG.skill2 = 'none'; PROG.talentVersion = 2; if (had) PROG.talentsBack = 1; }
  /* THE DRAIN WENT AND THE WARD CAME (v3): the Death Knight's third tree was rebuilt round BLOOD WARD, so every point he had in
     the old DRAIN tree comes back to him, once, and he is told. Nobody else's tree changed, and nobody else is told. */
  if ((PROG.talentVersion || 1) < 3) { const mm = PROG.talents.reaper; let had = false;
    if (mm) for (const id of ['deepToll', 'deathwatch', 'longPassing', 'scytheThrown', 'drainWalk', 'longStride', 'deathGrip', 'lastRites', 'gripAll', 'hunger']) if (mm[id]) { had = true; delete mm[id]; }
    if (had) for (const k of ['skill', 'skill2']) if (PROG[k] === 'scytheThrown' || PROG[k] === 'deathGrip') PROG[k] = 'none';
    PROG.talentVersion = 3; if (had) PROG.talentsBackHero = 'reaper'; }
  try { for (const hh in PROG.talents) { const mm = PROG.talents[hh]; for (const id in mm) { const nd = TREE.find(q => q.hero === hh && q.id === id); if (!nd) delete mm[id]; else if (mm[id] > nd.max) mm[id] = nd.max; } } } catch {}   /* ranks past a trimmed tree come back as points */ }
function loadSlot(i) { slot = i; for (const k in PROG) delete PROG[k]; Object.assign(PROG, readSlot(i) || {}); progDefaults(); try { localStorage.setItem('bracken.slot', String(i)); } catch {} }
function eraseSlot(i) { try { localStorage.removeItem(slotKey(i)); if (i === 0) localStorage.removeItem('bracken.progress'); } catch {} if (i === slot) { for (const k in PROG) delete PROG[k]; progDefaults(); } }
function saveProgress() { try { localStorage.setItem(slotKey(slot), JSON.stringify(PROG)); } catch {} }
loadSlot(slot);

