      for (const e of enemies) if (e.alive && !e.harmless && Math.abs(e.x - m.tx) < 44 && Math.abs((e.y - e.h / 2) - (m.ty - 10)) < 40) { hurtEnemy(e, e.maxHp ? Math.round(dmg * 0.6) : dmg, m.tx, false); if (!e.maxHp) { e.burn = Math.max(e.burn || 0, 2); flinch(e); } }
