  for (let i = 0; i < 18; i++) parts.push({ x: P.x + (Math.random() - 0.5) * 100, y: P.y, vx: (Math.random() - 0.5) * 30, vy: -30 - Math.random() * 60, life: 0.8, max: 0.8, col: Math.random() < 0.5 ? '#8fd160' : '#2a3a24', size: 2, grav: 50 });
