  if ((PROG.guardHeavy || 0) >= 4) return;
  PROG.guardHeavy = (PROG.guardHeavy || 0) + 1; hintT = 4;
  hintMsg = 'A GUARD TURNS A LIGHT BLOW. HOLD ' + (SET.swapZX ? 'Z' : 'X') + ' FOR A HEAVY ONE AND IT GOES THROUGH.';
