      const struck = hb && overlap(hb, { l: pr.x - 12, r: pr.x + 12, t: pr.y - 22, b: pr.y }) && !P.hitSet.has(pr);
      if (struck) { P.hitSet.add(pr);
        if (pr.cool > 0) SFX.clank();
        else { pr.cool = 0.9; pr.spin = 0.7; let n = 0, nd = 1; for (const z of (L.gusts || [])) if (z.helm === pr.id) { z.flip = !z.flip; n++; nd = z.dir * (z.flip ? -1 : 1); }
          SFX.ropeHaul(); SFX.gust(); shakeCam(2); sparks(pr.x, pr.y - 12, P.face, 4);
          number(pr.x, pr.y - 32, n ? 'THE WIND COMES ROUND' : 'NOTHING ANSWERS', n ? '#bfe6f5' : '#9aa39a');
          for (let k = 0; k < 24 && n; k++) parts.push({ x: camX + Math.random() * VW, y: camY + Math.random() * VH, vx: nd * (180 + Math.random() * 80), vy: 0, life: 0.35, max: 0.35, col: '#dfe8c0', size: 1, grav: 0 }); } }
