  SFX.clank(); SFX.thud(); number(P.x, P.y - 30, BALLAST_NAME[pr.kind] || 'BALLAST', '#bfe6f5');
  burst(pr.x, pr.y, 6, ['#8a919c', '#bfe6f5'], 40, 0.4);
