    if (keys.left) edCam.x -= sp; if (keys.right) edCam.x += sp;
    if (keys.up) edCam.y -= sp; if (keys.down) edCam.y += sp;
    edCam.x = Math.max(0, Math.min(LW * TS - VW, edCam.x)); edCam.y = Math.max(0, Math.min(LH * TS - VH, edCam.y));
