    if (sel) { g.fillStyle = 'rgba(143,209,96,0.14)'; g.fillRect(x + 4, yy - 2, w - 8, rowH - 2); g.fillStyle = UI.sel; g.fillRect(x + 4, yy - 2, 2, rowH - 2); }
